genes=readLines(file.path(cfg$inputs$epi_cache,'genes.txt'));gs=rd('config/gene_sets.tsv');allg=unique(gs$gene);al=as.data.table(AnnotationDbi::select(org.Hs.eg.db,intersect(allg,keys(org.Hs.eg.db,'SYMBOL')),columns='ALIAS',keytype='SYMBOL'));out=rbindlist(lapply(allg,function(g){v=if(g%in%genes)g else unique(al[SYMBOL==g&ALIAS%in%genes,ALIAS]);data.table(gene=g,input_gene=if(length(v)==1)v else NA_character_,mapping=if(g%in%genes)'exact_SYMBOL'else if(length(v)==1)'unique_org.Hs.eg.db_ALIAS_in_background'else 'missing_or_ambiguous',candidate=paste(v,collapse=';'))}));wt(out,'00_audit/epi_signature_mapping.tsv')
